using System.IO;using System.Text.Json;using System.Text.RegularExpressions;using System.Windows;using System.Windows.Controls;using System.Globalization;
record LogRow(int Line,DateTimeOffset? Time,string Level,string Message);
class Program{
 static LogRow Parse(string line,int index){string text=line,time="",level="";if(line.TrimStart().StartsWith('{'))try{using var d=JsonDocument.Parse(line);var r=d.RootElement;if(r.TryGetProperty("message",out var m))text=m.ToString();if(r.TryGetProperty("timestamp",out var t))time=t.ToString();if(r.TryGetProperty("level",out var l))level=l.ToString().ToUpperInvariant();}catch(JsonException){}if(time=="")time=line.Split(' ',2)[0];DateTimeOffset? date=DateTimeOffset.TryParse(time,CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal,out var parsed)?parsed:null;if(level=="")level=Regex.Match(line,@"\b(ERROR|WARN|INFO|DEBUG|TRACE|FATAL)\b",RegexOptions.IgnoreCase).Value.ToUpperInvariant();return new(index,date,level==""?"UNKNOWN":level,text);}
 [STAThread]static int Main(string[]args){if(args.Contains("--self-test")){var a=Parse("2030-01-01T10:00:00Z ERROR broken",1);var b=Parse("{\"timestamp\":\"2030-01-01T09:00:00Z\",\"level\":\"info\",\"message\":\"hello\"}",2);return a.Level=="ERROR"&&a.Time>b.Time&&b.Message=="hello"&&Parse("plain",3).Time==null?0:1;}var app=new Application();var w=new Window{Title="Log Timeline Studio",Width=1100,Height=700};var root=new DockPanel{Margin=new Thickness(16)};w.Content=root;var bar=new StackPanel{Orientation=Orientation.Horizontal};DockPanel.SetDock(bar,Dock.Top);root.Children.Add(bar);var path=new TextBox{Width=400,Margin=new Thickness(4)};var filter=new TextBox{Width=220,Margin=new Thickness(4),ToolTip="Search text"};var levels=new ComboBox{Width=100,ItemsSource=new[]{"ALL","ERROR","WARN","INFO","DEBUG","UNKNOWN"},SelectedIndex=0};var count=new TextBlock{Margin=new Thickness(10)};bar.Children.Add(path);bar.Children.Add(filter);bar.Children.Add(levels);var grid=new DataGrid{IsReadOnly=true,AutoGenerateColumns=true};root.Children.Add(grid);var rows=new List<LogRow>();void Draw(){var result=rows.Where(r=>(levels.Text=="ALL"||r.Level==levels.Text)&&r.Message.Contains(filter.Text,StringComparison.OrdinalIgnoreCase)).OrderBy(r=>r.Time??DateTimeOffset.MaxValue).ThenBy(r=>r.Line).ToList();grid.ItemsSource=result;count.Text=$"{result.Count}/{rows.Count} rows";}var open=new Button{Content="Load log",Padding=new Thickness(10)};bar.Children.Add(open);bar.Children.Add(count);open.Click+=(_,_)=>{try{var info=new FileInfo(path.Text);if(info.Length>10*1024*1024)throw new IOException("Limit: 10 MiB");var lines=File.ReadAllLines(path.Text);if(lines.Length>100000)throw new IOException("Limit: 100,000 lines");rows=lines.Select((s,i)=>Parse(s,i+1)).ToList();Draw();}catch(Exception e)when(e is IOException or UnauthorizedAccessException or ArgumentException){MessageBox.Show(e.Message);}};filter.TextChanged+=(_,_)=>Draw();levels.SelectionChanged+=(_,_)=>{w.Dispatcher.BeginInvoke(new Action(Draw));};app.Run(w);return 0;}
}
